<section class="container section"><div class="page-head"><div><p class="overline">KHẢO THÍ / BÀI THI</p><h1>Quản lý phách</h1><p class="muted">Bước 1: cấp mã phách → 2: đối chiếu → 3: niêm phong → 4: bàn giao.</p></div><a class="btn btn-light" href="<?=e(url('quan-tri/diem?exam_id='.$exam))?>">Điểm theo phách →</a></div>
<form method="get" action="<?=e(url('quan-tri/phach'))?>" class="filter-bar"><label>Kỳ tuyển sinh<select name="exam_id" onchange="this.form.submit()"><option value="">-- Chọn kỳ --</option><?php foreach($exams as $ex):?><option value="<?=$ex['id']?>" <?=$exam==(int)$ex['id']?'selected':''?>><?=e($ex['code'])?></option><?php endforeach;?></select></label><button class="btn btn-light">Xem</button></form>
<div class="two-col spaced"><section class="card"><h2>1. Đối chiếu và cấp phách</h2><p class="muted">Chọn đúng phòng và môn. Số bài phải khớp với số bài thực tế.</p><form class="stack" method="post" action="<?=e(url('quan-tri/phach/cap'))?>"><?=field('blind-allocate')?><input name="exam_id" type="hidden" value="<?=$exam?>"><label>Phòng thi<select name="room_id" required><?php foreach($rooms as $r):?><option value="<?=$r['id']?>"><?=e($r['code'].' – '.$r['school_name'])?></option><?php endforeach;?></select></label><label>Môn thi<select name="subject"><option>Ngữ văn</option><option>Ngoại ngữ</option><option>Toán</option></select></label><label>Số bài thực tế<input type="number" name="count" required min="1" placeholder="Ví dụ: 3"></label><button class="btn btn-main">Xác nhận số lượng & cấp phách</button></form></section>
<section class="card"><h2>2. Làm phách / bàn giao</h2><form class="stack" method="post" action="<?=e(url('quan-tri/phach/trang-thai'))?>"><?=field('blind-state')?><input name="exam_id" type="hidden" value="<?=$exam?>"><label>Túi phách<select name="package_code" required><?php foreach($packages as $p):?><option value="<?=e($p['package_code'])?>"><?=e($p['package_code'].' | '.$p['room_code'].' | '.$p['subject'].' | '.$p['state'])?></option><?php endforeach;?></select></label><label>Trạng thái thực hiện<select name="next_status"><option value="checked">Đã đối chiếu</option><option value="sealed">Đã cắt / niêm phong</option><option value="handed">Đã bàn giao</option></select></label><div class="form-grid"><label>Số bài làm<input name="count" type="number" min="1" required value="3"></label><label>Số đầu phách<input name="heads" type="number" min="1" required value="3"></label></div><label class="checkline"><input type="checkbox" name="confirmed" value="yes" required> Tôi đã hoàn tất công đoạn thực tế/mô phỏng.</label><button class="btn btn-main">Ghi nhận trạng thái</button></form><p class="hint">Hãy chuyển từng bước đúng thứ tự. Không thể bàn giao khi chưa đối chiếu/niêm phong.</p></section></div>
<section class="card spaced"><h2>Danh sách bài thi và mã phách</h2><div class="table-wrap"><table><thead><tr><th>Phòng</th><th>Môn</th><th>Mã phách</th><th>Túi phách</th><th>Trạng thái</th><th>Điểm</th></tr></thead><tbody><?php foreach($papers as $p):?><tr><td><?=e($p['room_code'])?></td><td><?=e($p['subject'])?></td><td><code><?=e($p['blind_code']??'Chưa cấp')?></code></td><td><?=e($p['package_code']??'—')?></td><td><span class="tag <?=$p['blind_status']==='handed'?'green':'gray'?>"><?=e($p['blind_status'])?></span></td><td><?=e($p['score']??'—')?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$papers):?><p class="empty">Chưa có bài thi trong kỳ được chọn.</p><?php endif;?></section>
<?php if(\App\Core\Auth::has('blind.mapping')):?><a class="btn btn-light spaced-inline" href="<?=e(url('quan-tri/phach/doi-chieu?exam_id='.$exam))?>">🔐 Xem bảng ghép danh tính (ghi nhật ký)</a><?php endif;?></section>
